:root {
  --bg-card: #1a1a2e;
  --bg-header: #16213e;
  --bg-stat: #0f3460;
  --bg-stat-highlight: #e94560;
  --bg-moves: #22223b;
  --bg-footer: #16213e;
  --accent-green: #06d6a0;
  --accent-yellow: #ffd166;
  --accent-orange: #f4845f;
  --text-primary: #edf2f4;
  --text-muted: #8d99ae;
  --text-dark: #1a1a2e;
  --border-subtle: #2d3561;
  --badge-done-bg: #06d6a0;
  --badge-wip-bg: #ffd166;
  --badge-next-bg: #4a4e69;
}

.parkour-log {
  width: 460px;
  background: var(--bg-card);
  border-radius: 14px;
  overflow: hidden;
  border: 1px solid var(--border-subtle);
}

.log-header {
  background: var(--bg-header);
  padding: 10px 16px 10px;
  border-bottom: 1px solid var(--border-subtle);
}

.log-meta {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 4px;
}

.log-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: var(--accent-green);
}

.log-date {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-muted);
}

.log-title-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.log-title {
  font-size: 18px;
  font-weight: 800;
  color: var(--text-primary);
  margin: 0;
  line-height: 1;
}

.location-name {
  font-size: 11px;
  color: var(--text-muted);
  font-weight: 500;
}

.stats-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  background: var(--border-subtle);
  border-bottom: 1px solid var(--border-subtle);
}

.stat-block {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 10px 8px;
  background: var(--bg-stat);
  gap: 2px;
}

.stat-block.highlight {
  background: var(--bg-stat-highlight);
}

.stat-value {
  font-size: 16px;
  font-weight: 800;
  color: var(--text-primary);
  line-height: 1;
}

.stat-label {
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.8px;
  text-transform: uppercase;
  color: var(--text-muted);
}

.stat-block.highlight .stat-label {
  color: var(--text-primary);
  opacity: 0.85;
}

.moves-section {
  background: var(--bg-moves);
  padding: 10px 16px;
}

.moves-title {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.2px;
  text-transform: uppercase;
  color: var(--text-muted);
  margin: 0 0 8px;
}

.moves-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.move-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 6px 10px;
  border-radius: 7px;
  border: 1px solid var(--border-subtle);
  background: var(--bg-card);
}

.move-name {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-primary);
}

.move-item.partial .move-name {
  color: var(--accent-yellow);
}

.move-item.pending .move-name {
  color: var(--text-muted);
}

.move-badge {
  font-size: 10px;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 20px;
}

.move-badge.done {
  background: var(--badge-done-bg);
  color: var(--text-dark);
}

.move-badge.wip {
  background: var(--badge-wip-bg);
  color: var(--text-dark);
}

.move-badge.next {
  background: var(--badge-next-bg);
  color: var(--text-primary);
}

.log-footer {
  background: var(--bg-footer);
  padding: 8px 16px;
  display: flex;
  align-items: center;
  gap: 8px;
  border-top: 1px solid var(--border-subtle);
}

.trainer-label {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-muted);
}

.trainer-name {
  font-size: 12px;
  font-weight: 700;
  color: var(--accent-orange);
  flex: 1;
}

.save-btn {
  background: var(--accent-green);
  color: var(--text-dark);
  border: none;
  border-radius: 7px;
  padding: 6px 14px;
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
  letter-spacing: 0.5px;
}
